#!/usr/bin/env python3
import os
import time

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
STATUS = os.path.join(ROOT, "job.status")
STARTED = os.path.join(ROOT, "job.started")

if not os.path.exists(STATUS):
    print("no job started")
else:
    status = open(STATUS, encoding="utf-8").read().strip()
    elapsed = ""
    if os.path.exists(STARTED):
        try:
            elapsed = " (%.1fs since start)" % (time.time() - float(open(STARTED, encoding="utf-8").read().strip()))
        except ValueError:
            pass
    print("status: %s%s" % (status, elapsed))
